@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): warm stone (#f5f1ee) page, crisp white (#ffffff) cards and newsletter band,
   pure black (#000000) text, 30% black hairlines, and vermilion orange (#ff5e2b) CTAs with black label text. */
:root {
  --background: #f5f1ee;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #ff5e2b;
  --primary-foreground: #000000;
  --secondary: #e8e4e1;
  --secondary-foreground: #000000;
  --muted: #e8e4e1;
  --muted-foreground: #413a3a;
  --accent: #ff5e2b;
  --accent-foreground: #000000;
  --destructive: #db2020;
  --destructive-foreground: #ffffff;
  --border: rgba(0, 0, 0, 0.3);
  --input: rgba(0, 0, 0, 0.3);
  --ring: #ff5e2b;
  --highlight: #ffa41c;
  --highlight-foreground: #000000;
  --glow: #ff362a;
  --chart-1: #ff5e2b;
  --chart-2: #ffa41c;
  --chart-3: #ff362a;
  --chart-4: #2d4fff;
  --chart-5: #968b88;
  --sidebar: #f5f1ee;
  --sidebar-foreground: #000000;
  --sidebar-primary: #ff5e2b;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #e8e4e1;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: rgba(0, 0, 0, 0.2);
  --sidebar-ring: #ff5e2b;

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 86rem;
  --page-gutter: 1.25rem;
  --section-y: 5.5rem;
}

/* Dark: pure black (#000000) backdrop for the hero, mission band, and footer,
   with crisp white text, charcoal (#241f1f) utility controls, and vermilion CTAs. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #0a0a0a;
  --card-foreground: #ffffff;
  --popover: #141111;
  --popover-foreground: #ffffff;
  --primary: #ff5e2b;
  --primary-foreground: #000000;
  --secondary: #241f1f;
  --secondary-foreground: #ffffff;
  --muted: #1b1717;
  --muted-foreground: #968b88;
  --accent: #241f1f;
  --accent-foreground: #ffffff;
  --destructive: #fc4646;
  --destructive-foreground: #000000;
  --border: rgba(255, 255, 255, 0.24);
  --input: rgba(255, 255, 255, 0.24);
  --ring: #ff5e2b;
  --highlight: #ffa41c;
  --highlight-foreground: #000000;
  --glow: #ff362a;
  --chart-1: #ff5e2b;
  --chart-2: #ffa41c;
  --chart-3: #ff362a;
  --chart-4: #2d4fff;
  --chart-5: #968b88;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ff5e2b;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #241f1f;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgba(255, 255, 255, 0.16);
  --sidebar-ring: #ff5e2b;
}
